using System;using System.Collections.Generic;using RimWorld;using UnityEngine;using Verse;
namespace ElementalHearts {
 public sealed class AwakeningPulse:IExposable {public Pawn source;public IntVec3 center;public string element;public int due;public void ExposeData(){Scribe_References.Look(ref source,"source");Scribe_Values.Look(ref center,"center");Scribe_Values.Look(ref element,"element");Scribe_Values.Look(ref due,"due");}}
 [StaticConstructorOnStartup]
 public sealed class MapComponent_AwakeningBurst:MapComponent {
  List<AwakeningPulse> pending=new List<AwakeningPulse>();
  struct Flash{public bool active;public IntVec3 cell;public int start;public string element;}
  readonly Flash[] flashes=new Flash[32];int cursor;static Mesh ring;static Material solid;MaterialPropertyBlock block;
  public MapComponent_AwakeningBurst(Map map):base(map){}
  public override void ExposeData(){if(Scribe.mode==LoadSaveMode.Saving)pending.RemoveAll(e=>e==null||e.source==null||e.source.Destroyed||!e.source.Spawned||e.source.Map!=map);Scribe_Collections.Look(ref pending,"EH_awakeningPulses",LookMode.Deep);if(pending==null)pending=new List<AwakeningPulse>();}
  public override void FinalizeInit(){foreach(var e in pending){if(e==null||e.source==null||!e.center.InBounds(map))continue;flashes[cursor]=new Flash{active=true,cell=e.center,start=e.due-1,element=e.element};cursor=(cursor+1)%flashes.Length;}}
  public void Enqueue(Pawn p,string element){foreach(var e in pending)if(e.source==p)return;int now=Find.TickManager.TicksGame;pending.Add(new AwakeningPulse{source=p,center=p.Position,element=element,due=now+1});flashes[cursor]=new Flash{active=true,cell=p.Position,start=now,element=element};cursor=(cursor+1)%flashes.Length;ElementalAudio.Play(p,"Explosion_Bomb","EH_TransformLock");}
  public override void MapComponentTick(){int now=Find.TickManager.TicksGame,spent=0;while(pending.Count>0&&spent<4){var e=pending[0];if(e!=null&&e.due>now)break;pending.RemoveAt(0);spent++;if(e!=null)Impact(e);}}
  void Impact(AwakeningPulse e){var p=e.source;if(p==null||p.Destroyed||!p.Spawned||p.Map!=map||!e.center.InBounds(map))return;var ids=new HashSet<int>();var targets=new List<Pawn>();foreach(var cell in GenRadial.RadialCellsAround(e.center,3.5f,true)){if(!cell.InBounds(map)||!LightningCombat.ClearLine(e.center,cell,map))continue;foreach(var thing in cell.GetThingList(map)){var victim=thing as Pawn;if(victim==null||victim==p||victim.Dead||victim.Downed||!ElementalCombatPolicy.TargetAllowed(false,ElementalHeartsMod.Settings.friendlyFire,victim.IsPrisoner,victim.HostileTo(p))||!ids.Add(victim.thingIDNumber))continue;targets.Add(victim);if(targets.Count>=16)break;}if(targets.Count>=16)break;}
   foreach(var victim in targets){if(victim.Dead||victim.Downed||!victim.Spawned||victim.Map!=map)continue;if(!ElementalNonLethal.TryApply(p,victim,18))victim.TakeDamage(new DamageInfo(DefDatabase<DamageDef>.GetNamed("EH_AwakeningShockwave"),18,.5f,-1,p));if(!victim.Dead&&!victim.Downed)victim.stances.stunner.StunFor(60,p);}
  }
  static void Prepare(){if(ring!=null)return;const int n=48;var vertices=new Vector3[(n+1)*2];var triangles=new int[n*6];for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;vertices[i*2]=new Vector3(Mathf.Sin(a)*.43f,0,Mathf.Cos(a)*.43f);vertices[i*2+1]=new Vector3(Mathf.Sin(a)*.5f,0,Mathf.Cos(a)*.5f);if(i<n){int k=i*2,j=i*6;triangles[j]=k;triangles[j+1]=k+1;triangles[j+2]=k+2;triangles[j+3]=k+1;triangles[j+4]=k+3;triangles[j+5]=k+2;}}ring=new Mesh();ring.vertices=vertices;ring.triangles=triangles;ring.RecalculateNormals();ring.RecalculateBounds();solid=SolidColorMaterials.SimpleSolidColorMaterial(Color.white,true);}
  public override void MapComponentDraw(){if(map!=Find.CurrentMap||Find.CameraDriver==null||ElementalHeartsMod.Settings.effectOpacity<=0)return;Prepare();if(block==null)block=new MaterialPropertyBlock();int now=Find.TickManager.TicksGame;var visible=Find.CameraDriver.CurrentViewRect.ExpandedBy(5);for(int i=0;i<flashes.Length;i++){var f=flashes[i];if(!f.active)continue;float t=(now-f.start)/45f;if(t>=1){flashes[i]=new Flash();continue;}if(!visible.Contains(f.cell)||f.cell.Fogged(map))continue;Color color=f.element=="Earth"?new Color(.9f,.6f,.22f):f.element=="Flame"?new Color(1,.35f,.06f):f.element=="Wind"?new Color(.65f,1,.75f):f.element=="Lightning"?new Color(.65f,.75f,1):new Color(.2f,.8f,1);color.a=(1-t)*ElementalHeartsMod.Settings.effectOpacity;var at=f.cell.ToVector3Shifted();at.y=AltitudeLayer.MoteOverhead.AltitudeFor();block.SetColor(ShaderPropertyIDs.Color,color);float size=.6f+7f*(1-(1-t)*(1-t));Graphics.DrawMesh(ring,Matrix4x4.TRS(at,Quaternion.identity,new Vector3(size,1,size)),solid,0,null,0,block);color.a*=.45f;block.SetColor(ShaderPropertyIDs.Color,color);Graphics.DrawMesh(ring,Matrix4x4.TRS(at,Quaternion.identity,new Vector3(size*.65f,1,size*.65f)),solid,0,null,0,block);for(int ray=0;ray<12;ray++){float a=(ray*30+f.start%30)*Mathf.Deg2Rad;var pos=at+new Vector3(Mathf.Sin(a),0,Mathf.Cos(a))*size*.4f;Graphics.DrawMesh(MeshPool.plane10,Matrix4x4.TRS(pos,Quaternion.AngleAxis(-ray*30-f.start%30,Vector3.up),new Vector3(.05f*(1-t),1,.5f+.5f*(1-t))),solid,0,null,0,block);}}}
 }
}
